{"sql": "SELECT 
  ROUND(
    AVG(
      ROUND(ABS(EXTRACT(YEAR FROM CAST(final_game AS DATE)) - EXTRACT(YEAR FROM CAST(debut AS DATE))), 2)
      + ROUND(ABS(EXTRACT(MONTH FROM CAST(final_game AS DATE)) - EXTRACT(MONTH FROM CAST(debut AS DATE))), 2) / 12.0
      + ROUND(ABS(EXTRACT(DAY FROM CAST(final_game AS DATE)) - EXTRACT(DAY FROM CAST(debut AS DATE))), 2) / 365.0
    ), 2
  ) as avg_career_span
FROM player
WHERE debut <> '' AND final_game <> ''", "preview_rows": 5}
